class FenwickTree {
  constructor(n) {
    this.n = n;
    // 1-indexed; index 0 is unused
    this.bit = new Array(n + 1).fill(0);
  }

  // add delta to position i (1-indexed)
  update(i, delta) {
    for (; i <= this.n; i += i & (-i)) {
      this.bit[i] += delta;
    }
  }

  // prefix sum [1..i]
  prefixSum(i) {
    let sum = 0;
    for (; i > 0; i -= i & (-i)) {
      sum += this.bit[i];
    }
    return sum;
  }

  // range sum [l..r] (both 1-indexed)
  rangeSum(l, r) {
    return this.prefixSum(r) - this.prefixSum(l - 1);
  }
}

// Build from existing array in O(n)
function buildBIT(arr) {
  const ft = new FenwickTree(arr.length);
  for (let i = 0; i < arr.length; i++) {
    // arr is 0-indexed; BIT is 1-indexed
    ft.update(i + 1, arr[i]);
  }
  return ft;
}
